        Question(id = generateId(), text = "O metabolismo ácido das crassuláceas (CAM) confere uma vantagem adaptativa crítica a plantas de ambientes áridos. Qual é a estratégia temporal subjacente a este mecanismo de fixação de carbono?", options = listOf("A abertura estomática diurna para maximizar a captação de luz, conjugada com a fixação de CO2 pela enzima rubisco no mesofilo.", "A compartimentação espacial exclusiva entre as células do mesofilo e as células da bainha do feixe vascular.", "A fixação noturna de CO2 originando ácidos orgânicos vacuolares, que são descarboxilados de dia com os estomas encerrados.", "A substituição total da fotorrespiração por vias anaeróbias que geram ATP na ausência de oxigénio atmosférico."), correctOptionIndex = 2, difficulty = "Avançada", subject = "Biologia"),
        Question(id = generateId(), text = "O sistema imunitário adaptativo gera um repertório virtualmente infinito de anticorpos e recetores de células T. Qual mecanismo molecular é o responsável primordial por gerar esta vasta diversidade nos linfócitos em maturação?", options = listOf("A elevada taxa de mutação induzida por agentes patogénicos circulantes no plasma sanguíneo.", "O splicing alternativo do RNA mensageiro em células maduras expostas a diferentes antigénios.", "A recombinação somática V(D)J dos segmentos génicos catalisada pelas enzimas RAG1 e RAG2.", "A amplificação de genes específicos no genoma através de plasmídeos de resistência adquiridos."), correctOptionIndex = 2, difficulty = "Avançada", subject = "Biologia"),
        Question(id = generateId(), text = "Na dinâmica de ecossistemas maduros, a relação entre a produtividade primária bruta (PPB) e a respiração total da comunidade (R) altera-se ao longo da sucessão ecológica. Qual padrão caracteriza o estágio clímax?", options = listOf("A PPB excede largamente a R, resultando num acúmulo contínuo e exponencial de biomassa no sistema.", "A razão PPB/R aproxima-se de 1, indicando um estado de equilíbrio onde a biomassa total estabiliza.", "A R ultrapassa a PPB, o que evidencia o colapso iminente das redes tróficas e a perda de biodiversidade.", "A PPB reduz-se a zero, uma vez que a comunidade atinge a sua capacidade máxima de reciclagem de nutrientes inorgânicos."), correctOptionIndex = 1, difficulty = "Avançada", subject = "Biologia"),
        Question(id = generateId(), text = "A manutenção do potencial de repouso da membrana neuronal requer gasto constante de energia. Qual é a contribuição estrutural da bomba de sódio-potássio (Na+/K+ ATPase) para esta polarização?", options = listOf("O transporte passivo de iões a favor do gradiente, permitindo o influxo rápido de sódio durante a despolarização.", "A extrusão de três iões Na+ para cada dois iões K+ introduzidos na célula, gerando um défice de cargas positivas no meio intracelular.", "A oclusão transitória dos canais de fuga de potássio, impedindo que o axónio atinja o limiar de excitabilidade.", "A síntese intracelular de aniões orgânicos inodifusíveis que neutralizam eletrostaticamente os catiões extracelulares."), correctOptionIndex = 1, difficulty = "Avançada", subject = "Biologia"),
        Question(id = generateId(), text = "A pleiotropia é um fenómeno genético frequente que impõe restrições evolutivas significativas às populações. O que caracteriza estritamente este conceito genético?", options = listOf("A interação supressora em que o alelo de um locus inibe a expressão fenotípica de um locus distinto.", "A determinação de múltiplas características fenotípicas aparentemente não relacionadas por um único gene.", "A necessidade de múltiplos alelos em loci diferentes para a expressão de um único traço quantitativo.", "A alteração da taxa de mutação basal mediada pela exposição contínua a stressores ambientais."), correctOptionIndex = 1, difficulty = "Avançada", subject = "Biologia"),
        Question(id = generateId(), text = "A regulação da expressão génica em eucariotas apresenta níveis de complexidade ausentes nos procariotas. O mecanismo de splicing alternativo proporciona qual vantagem evolutiva crucial aos organismos superiores?", options = listOf("A tradução simultânea de múltiplos ribossomas num único transcrito, formando polissomas eficientes.", "A remoção exclusiva de exões não codificantes para garantir a replicação fiel do DNA mitocondrial.", "A produção de múltiplas isoformas proteicas estruturalmente distintas a partir de um único gene.", "O silenciamento irreversível do cromossoma X em fêmeas por metilação massiva das histonas."), correctOptionIndex = 2, difficulty = "Avançada", subject = "Biologia"),
        Question(id = generateId(), text = "Em mamíferos, a resposta endócrina ao stress prolongado é orquestrada pelo eixo hipotálamo-hipófise-suprarrenal. Qual é a consequência sistémica crónica da hipersecreção de cortisol?", options = listOf("A estimulação da glicogénese hepática e da osteoblastogénese, resultando num aumento da densidade óssea.", "A imunossupressão severa, acompanhada de hiperglicemia e redistribuição anómala da gordura corporal.", "O aumento agudo da taxa de filtração glomerular e consequente hiponatremia devido à inibição da aldosterona.", "A hipertrofia muscular esquelética induzida pela aceleração da síntese proteica nas fibras brancas."), correctOptionIndex = 1, difficulty = "Avançada", subject = "Biologia"),
        Question(id = generateId(), text = "Durante o desenvolvimento embrionário, a distinção entre protostómios e deuterostómios é basilar para a filogenia animal. Qual característica morfogenética define exclusivamente os cordados e os equinodermes nestas fases iniciais?", options = listOf("O desenvolvimento do blastóporo na boca e uma clivagem do tipo espiral e determinada.", "A formação do celoma por esquizocelia a partir do fracionamento de massas mesodérmicas sólidas.", "O desenvolvimento do blastóporo no ânus, acompanhado de uma clivagem radial e indeterminada.", "A ausência total de tecidos embrionários verdadeiros, com organização estrutural ao nível celular."), correctOptionIndex = 2, difficulty = "Avançada", subject = "Biologia"),
        Question(id = generateId(), text = "A adaptação à excreção de resíduos azotados varia conforme a ecologia do organismo. Qual a vantagem evolutiva primária da excreção de ácido úrico pelos vertebrados uricotélicos (como aves e répteis)?", options = listOf("A elevada solubilidade em água, permitindo a eliminação rápida através de membranas branquiais ou cutâneas.", "O baixo custo energético de síntese comparativamente à amónia, poupando reservas de ATP metabólico.", "A insolubilidade e a baixa toxicidade, minimizando a perda de água necessária para o armazenamento e excreção embrionária.", "A capacidade de ser utilizado como substrato alternativo para a respiração celular em condições de hipoxia."), correctOptionIndex = 2, difficulty = "Avançada", subject = "Biologia"),
        Question(id = generateId(), text = "No contexto da genética de populações, o teorema de Hardy-Weinberg descreve uma população hipotética em equilíbrio estático. Qual premissa biológica é indispensável para que as frequências alélicas permaneçam constantes ao longo das gerações?", options = listOf("A existência de uma forte pressão seletiva direcional que favoreça os fenótipos homozigotos.", "A ocorrência de cruzamentos totalmente aleatórios (panmixia) numa população de grande tamanho.", "O aumento progressivo da taxa de mutação génica para garantir a introdução de novos alelos.", "O fluxo génico constante oriundo de populações periféricas para manter a variabilidade intrapopulacional."), correctOptionIndex = 1, difficulty = "Avançada", subject = "Biologia"),
        Question(id = generateId(), text = "Os retrovírus, como o VIH, utilizam a transcriptase reversa para integrar o seu genoma na célula hospedeira. Sob a ótica do dogma central da biologia molecular, qual o percurso inusitado do fluxo de informação genética mediado por esta enzima?", options = listOf("A conversão de uma molécula de RNA de cadeia simples num DNA complementar de cadeia dupla.", "A tradução direta do genoma viral de RNA em proteínas do capsídeo sem a intermediação de ribossomas.", "A transcrição reversa de sequências polipeptídicas para recriar as fitas matrizes de nucleótidos.", "A replicação autónoma de moléculas de DNA dupla hélice exclusivamente no citoplasma do hospedeiro."), correctOptionIndex = 0, difficulty = "Avançada", subject = "Biologia"),
        Question(id = generateId(), text = "O modelo da coesão-tensão explica a ascensão da seiva bruta no xilema de árvores de grande porte. Que força física impulsiona primordialmente o movimento ascendente da coluna de água contínua ao longo dos vasos?", options = listOf("A forte pressão positiva radicelar gerada pelo transporte ativo de sais no córtex da raiz.", "A capilaridade passiva promovida pelas células companheiras dos tubos crivosos no floema.", "A tensão negativa (pressão hidrostática negativa) gerada pela transpiração nos estomas das folhas.", "A contração rítmica e coordenada das células mortas dos traqueídos impulsionada por hidrólise de ATP."), correctOptionIndex = 2, difficulty = "Avançada", subject = "Biologia"),
        Question(id = generateId(), text = "O princípio da exclusão competitiva (Lei de Gause) estabelece um axioma central da dinâmica comunitária. O que postula este princípio biológico face à sobreposição de nichos ecológicos?", options = listOf("Espécies com elevada taxa reprodutiva cooperam espontaneamente quando enfrentam a mesma pressão de predação.", "Duas espécies não podem coexistir indefinidamente num ambiente estável se os seus nichos ecológicos forem idênticos.", "A diversidade de predadores de topo garante a exclusão dos produtores primários dominantes num ecossistema fechado.", "O mutualismo obrigatório surge invariavelmente sempre que os recursos limitantes se esgotam no habitat."), correctOptionIndex = 1, difficulty = "Avançada", subject = "Biologia"),
        Question(id = generateId(), text = "Na regulação da contração do músculo esquelético, o ião cálcio (Ca2+) desempenha um papel de sinalização intracelular vital. Qual é o mecanismo de ação molecular direto do cálcio no sarcómero?", options = listOf("Liga-se à miosina, induzindo a clivagem do ATP necessária para o golpe de força da cabeça motora.", "Liga-se à troponina, provocando uma mudança conformacional que desloca a tropomiosina dos locais de ligação da actina.", "Inibe a enzima acetilcolinesterase na fenda sináptica, prolongando a duração do potencial de ação da placa motora.", "Despolariza o retículo sarcoplasmático ao ativar os canais de sódio voltagem-dependentes na membrana do túbulo T."), correctOptionIndex = 1, difficulty = "Avançada", subject = "Biologia"),
        Question(id = generateId(), text = "O complexo principal de histocompatibilidade (MHC) é a base do reconhecimento imunitário do \"próprio\" e do \"não próprio\". Funcionalmente, qual é a distinção primordial entre as moléculas de MHC de classe I e as de classe II?", options = listOf("O MHC I apresenta antigénios intracelulares aos linfócitos T citotóxicos, enquanto o MHC II apresenta antigénios extracelulares fagocitados aos linfócitos T auxiliares.", "O MHC I está restrito aos macrófagos, enquanto o MHC II é expresso universalmente em todas as células nucleadas do organismo.", "O MHC I media a resposta alérgica humoral aguda, ao passo que o MHC II desencadeia a cascata de coagulação na imunidade inata.", "O MHC I sofre rápida recombinação somática no timo, contrastando com o padrão de hereditariedade mendeliana fixa do MHC II."), correctOptionIndex = 0, difficulty = "Avançada", subject = "Biologia"),
        Question(id = generateId(), text = "Na biologia do envelhecimento, o complexo ribonucleoproteico telomerase assume importância capital, estando fortemente ativo em células estaminais e linhagens tumorais. Qual é a sua exata função catalítica?", options = listOf("Reparar as quebras de dupla cadeia no DNA induzidas pela exposição cumulativa a espécies reativas de oxigénio.", "Adicionar sequências repetitivas ricas em guanina às extremidades 3' dos cromossomas lineares, compensando o encurtamento replicativo.", "Promover a degradação de proteínas senescentes mal dobradas no interior dos lisossomas através de ubiquitinação.", "Catalisar a metilação de promotores de oncogenes eucarióticos para prevenir a transição G1/S não autorizada."), correctOptionIndex = 1, difficulty = "Avançada", subject = "Biologia"),
        Question(id = generateId(), text = "A transmissão de sinais ao longo das fibras nervosas é regulada pelo fenómeno do período refratário. O que determina a absoluta incapacidade da fibra nervosa em gerar um novo potencial de ação durante o período refratário absoluto?", options = listOf("A ativação sustentada das bombas Na+/K+ que hiperpolarizam excessivamente a membrana para valores abaixo do repouso.", "O estado de inativação espacial dos canais de sódio voltagem-dependentes, cujos portões de inativação se encontram fechados e irresponsivos.", "O esgotamento transitório dos neurotransmissores encapsulados nas vesículas pré-sinápticas do botão terminal.", "A ligação inibitória irreversível da enzima acetilcolinesterase aos recetores nicotínicos pós-sinápticos."), correctOptionIndex = 1, difficulty = "Avançada", subject = "Biologia"),
        Question(id = generateId(), text = "O fenómeno de biomagnificação trófica (ou magnificação biológica) representa um risco toxicológico severo. Qual particularidade físico-química de certos poluentes artificiais, como o DDT, permite este acúmulo sistémico nas cadeias alimentares?", options = listOf("A sua natureza hidrossolúvel, que impede a excreção renal e promove a difusão no plasma sanguíneo dos predadores de topo.", "A sua elevada lipossolubilidade e resistência à biodegradação, levando ao seu armazenamento progressivo nos tecidos adiposos dos níveis tróficos superiores.", "A sua semelhança estrutural com as enzimas digestivas, o que acelera o metabolismo basal das presas consumidas pelos consumidores primários.", "A alta volatilidade, facilitando a fixação cutânea imediata em organismos produtores durante os eventos de chuva ácida."), correctOptionIndex = 1, difficulty = "Avançada", subject = "Biologia"),
        Question(id = generateId(), text = "O conceito de homologia é basilar para a reconstrução de árvores filogenéticas consistentes. Na morfologia evolutiva comparada, como se diferenciam estruturalmente as características homólogas das análogas?", options = listOf("Homologias derivam de pressões seletivas convergentes, enquanto as analogias resultam de ancestralidade partilhada evidente na ontogenia.", "Homologias evidenciam um mesmo padrão embrionário originado de um ancestral comum, independentemente da função atual, enquanto as analogias resultam de convergência evolutiva.", "Homologias ocorrem estritamente entre táxons do mesmo género, e as analogias manifestam-se apenas entre reinos biológicos distintos.", "Homologias são sempre rudimentares (órgãos vestigiais), ao passo que as analogias desempenham as funções fisiológicas mais vitais do organismo adaptado."), correctOptionIndex = 1, difficulty = "Avançada", subject = "Biologia"),
        Question(id = generateId(), text = "A biotecnologia revolucionou-se com o sistema CRISPR-Cas9, derivado da imunidade adaptativa bacteriana. Qual componente do sistema confere a altíssima especificidade no reconhecimento do alvo no genoma a editar?", options = listOf("A atividade de polimerização intrínseca da proteína Cas9 que sintetiza a nova fita com base num plasmídeo doador.", "O RNA guia (gRNA) modificado que emparelha por complementaridade com a sequência exata de DNA a ser clivada.", "O motivo de sequência protospaçadora adjacente (PAM) localizado na própria fita de RNA mensageiro viral transcrito.", "Os fatores de reparação de extremidades não homólogas (NHEJ) que induzem indels (inserções ou deleções) no local de corte."), correctOptionIndex = 1, difficulty = "Avançada", subject = "Biologia"),
        Question(id = generateId(), text = "A conjugação bacteriana representa um dos mecanismos primários da transferência genética horizontal. Qual é a estrutura mediadora fundamental que permite a concretização biológica deste processo?", options = listOf("A formação de uma ponte citoplasmática temporária mediada por um pili sexual (ou pili F) codificado por um plasmídeo.", "A integração fortuita de moléculas livres de DNA circular presentes no biofilme através da permeabilidade transiente da membrana.", "A injeção de material genético cromossómico orquestrada pelo ciclo lítico de um vírus bacteriófago vetor.", "A fusão binária completa de duas células vegetativas que partilham posteriormente o mesmo genóforo no nucleoide recém-formado."), correctOptionIndex = 0, difficulty = "Avançada", subject = "Biologia"),
        Question(id = generateId(), text = "O padrão de hereditariedade ligada ao cromossoma X impõe particularidades fenotípicas nas populações humanas. Por que razão os homens apresentam uma incidência consideravelmente maior de doenças recessivas ligadas a este cromossoma, como a hemofilia?", options = listOf("Devido ao fenómeno da inativação aleatória do cromossoma X (corpúsculo de Barr), que expõe alelos deletérios na espermatogénese.", "Porque possuem hemizigotia para o cromossoma X, o que significa que a presença de um único alelo recessivo é suficiente para a expressão da anomalia.", "Visto que o cromossoma Y carrega um fator de transcrição ativador que potencia a penetrância dos alelos patogénicos do X herdado do pai.", "Como resultado da elevada instabilidade telomérica do único cromossoma X presente nas células somáticas masculinas durante a mitose embrionária."), correctOptionIndex = 1, difficulty = "Avançada", subject = "Biologia")
    )

    val fisicaQuestions = listOf(
        Question(id = generateId(), text = "O colapso gravitacional de uma estrela para formar uma estrela de nêutrons resulta em um aumento dramático de sua velocidade angular. Qual princípio físico macroscópico fundamenta diretamente essa alteração cinemática intrínseca?", options = listOf("A conversão integral da energia potencial gravitacional em energia cinética translacional de escape.", "A conservação do momento angular em um sistema isolado submetido a um torque externo resultante nulo.", "O aumento relativístico da massa inercial devido às altíssimas velocidades das camadas externas.", "A dilatação do tempo nos polos da estrela gerada pela intensa curvatura do espaço-tempo."), correctOptionIndex = 1, difficulty = "Avançada", subject = "Física"),
        Question(id = generateId(), text = "Em um ciclo de Carnot operando de forma reversível, a variação total de entropia do universo é nula. No entanto, qual condição termodinâmica fundamental impede que uma máquina térmica real atinja esse rendimento ideal?", options = listOf("A incapacidade de converter integralmente o calor absorvido da fonte quente em trabalho útil.", "A ocorrência de transferência espontânea de calor entre corpos com diferenças finitas de temperatura, processo que gera entropia.", "A barreira física imposta pela impossibilidade de atingir o zero absoluto na fonte fria.", "A dependência exclusiva do rendimento em relação à natureza química do fluido de trabalho utilizado nas expansões isobáricas."), correctOptionIndex = 1, difficulty = "Avançada", subject = "Física"),
        Question(id = generateId(), text = "A Lei de Lenz determina o sentido da força eletromotriz induzida em um circuito fechado. Conceitualmente, essa formulação fenomenológica é a manifestação eletromagnética direta de qual princípio universal?", options = listOf("Da conservação da carga elétrica elementar no interior de condutores metálicos.", "Da conservação do fluxo magnético em superfícies gaussianas esféricas.", "Da conservação da energia mecânica translacional do ímã indutor.", "Da conservação da energia, garantindo que o trabalho mecânico realizado contra a força magnética induzida seja convertido em energia elétrica."), correctOptionIndex = 3, difficulty = "Avançada", subject = "Física"),
        Question(id = generateId(), text = "O efeito fotoelétrico representou um impasse para a teoria ondulatória clássica da luz. Qual constatação experimental exigiu estritamente a adoção do modelo de quantização da radiação eletromagnética em fótons?", options = listOf("A dependência linear da energia cinética máxima dos fotoelétrons em relação à intensidade do feixe luminoso.", "A existência de uma frequência de corte (frequência limiar) característica do material, abaixo da qual não ocorre emissão, independentemente da intensidade da luz.", "A difração acentuada dos elétrons ejetados ao atravessarem fendas de dimensões atômicas.", "A emissão contínua de radiação térmica em todos os comprimentos de onda por um corpo negro ideal."), correctOptionIndex = 1, difficulty = "Avançada", subject = "Física"),
        Question(id = generateId(), text = "O Princípio da Incerteza de Heisenberg impõe um limite fundamental à medição simultânea de variáveis conjugadas. Qual é a interpretação física estrutural desse limite na formulação da mecânica quântica?", options = listOf("Ele decorre da imperfeição tecnológica e dos erros sistêmicos intrínsecos aos aparelhos de medição macroscópicos.", "Ele reflete a natureza dual onda-partícula, onde a localização espacial de um pacote de ondas resulta necessariamente no alargamento do seu espectro de momento.", "Ele comprova que as órbitas eletrônicas são trajetórias elípticas bem definidas, mas momentaneamente inobserváveis.", "Ele estabelece que flutuações quânticas no vácuo podem violar a conservação da energia em escalas de tempo macroscópicas."), correctOptionIndex = 1, difficulty = "Avançada", subject = "Física"),
        Question(id = generateId(), text = "A Relatividade Restrita postula a invariância da velocidade da luz no vácuo para todos os referenciais inerciais. Como consequência cinemática direta desse postulado, qual é a relação entre o tempo próprio e o tempo medido por um observador em movimento relativo?", options = listOf("O tempo próprio, medido no referencial onde os eventos ocorrem na mesma coordenada espacial, é sempre o menor intervalo de tempo medido entre tais eventos.", "O tempo próprio é sistematicamente dilatado de forma proporcional ao quadrado da velocidade do referencial em movimento.", "A dilatação temporal ocorre exclusivamente em referenciais não-inerciais submetidos a altas acelerações centrípetas.", "Ambos os intervalos temporais permanecem rigorosamente iguais, desde que a velocidade relativa seja constante e retilínea."), correctOptionIndex = 0, difficulty = "Avançada", subject = "Física"),
        Question(id = generateId(), text = "A força de Coriolis é uma força inercial (fictícia) observada em referenciais em rotação. Em escala planetária, qual é o seu principal efeito cinemático na dinâmica da circulação atmosférica global?", options = listOf("O impulsionamento das correntes de convecção verticais que formam a Zona de Convergência Intertropical.", "A atração gravitacional anômala das massas de ar equatoriais em direção aos polos magnéticos da Terra.", "O desvio das massas de ar em movimento para a direita no Hemisfério Norte e para a esquerda no Hemisfério Sul, estruturando os sistemas ciclônicos e anticiclônicos.", "A aceleração uniforme dos ventos alísios em trajetórias perfeitamente paralelas à linha do Equador terrestre."), correctOptionIndex = 2, difficulty = "Avançada", subject = "Física"),
        Question(id = generateId(), text = "No experimento da fenda dupla de Young, a formação de um padrão de franjas numa tela evidencia a natureza ondulatória da luz. Qual condição óptica é rigorosamente essencial para a formação estável e contínua desse padrão de interferência?", options = listOf("As fontes emissoras secundárias devem produzir feixes de luz branca perfeitamente não-polarizada.", "As fendas devem ter larguras macroscópicas, substancialmente maiores que o comprimento de onda da luz incidente.", "As fontes de luz oriundas das fendas devem ser coerentes, mantendo uma diferença de fase constante ao longo do tempo.", "O meio de propagação entre as fendas e o anteparo deve possuir um alto índice de dispersão cromática."), correctOptionIndex = 2, difficulty = "Avançada", subject = "Física"),
        Question(id = generateId(), text = "A introdução da \"corrente de deslocamento\" por Maxwell generalizou a Lei de Ampère. Qual situação física paradoxal exigiu essa correção teórica para garantir a continuidade do campo magnético e a validade global da equação?", options = listOf("O cálculo da indução magnética gerada por um ímã permanente em queda livre através de uma espira de cobre.", "O fluxo contínuo e uniforme de elétrons livres ao longo de um condutor retilíneo ôhmico.", "A deflexão lateral de partículas alfa ao penetrarem em uma região de campo magnético uniforme.", "A geração de um campo magnético na região entre as placas de um capacitor em processo de carga, onde não há corrente de condução."), correctOptionIndex = 3, difficulty = "Avançada", subject = "Física"),
        Question(id = generateId(), text = "A equação de Bernoulli descreve o comportamento de fluidos ideais relacionando pressão, velocidade e elevação. Na dinâmica de voo, como essa formulação explica parcialmente a sustentação gerada por um perfil alar assimétrico?", options = listOf("A viscosidade do ar cria uma camada limite turbulenta que empurra mecanicamente a face inferior da asa para cima.", "A maior velocidade do escoamento do fluido sobre o extradorso (parte superior) resulta em uma redução localizada da pressão estática, gerando uma força resultante ascendente.", "A pressão dinâmica se anula no bordo de fuga, criando um vácuo que suga a aeronave em direção à estratosfera.", "O princípio da incompressibilidade garante que o fluido exerça pressão hidrostática idêntica em todas as superfícies planas expostas ao vento relativo."), correctOptionIndex = 1, difficulty = "Avançada", subject = "Física"),
        Question(id = generateId(), text = "O teorema da equipartição da energia conecta a temperatura termodinâmica aos graus de liberdade moleculares. Para um gás ideal diatômico à temperatura ambiente, quais graus de liberdade contribuem ativamente para a sua energia interna molar?", options = listOf("Exclusivamente os graus de liberdade translacionais, pois os movimentos rotacionais são amortecidos por colisões inelásticas.", "Os graus translacionais, rotacionais e vibracionais, todos totalmente excitados de acordo com os postulados da física clássica.", "Os graus translacionais e rotacionais, estando os graus de liberdade vibracionais majoritariamente \"congelados\" devido à quantização da energia.", "Apenas os graus vibracionais, visto que a simetria da molécula diatômica anula os momentos de inércia translacionais."), correctOptionIndex = 2, difficulty = "Avançada", subject = "Física"),
        Question(id = generateId(), text = "Em um oscilador harmônico amortecido, a energia mecânica do sistema é progressivamente dissipada. No regime de amortecimento crítico, qual é o comportamento cinemático observado quando a massa é deslocada de sua posição de equilíbrio e solta?", options = listOf("O sistema oscila em torno da posição de equilíbrio com uma amplitude que decai exponencialmente ao longo do tempo.", "O sistema retorna à posição de equilíbrio no menor intervalo de tempo possível sem realizar nenhuma oscilação.", "O sistema atinge o repouso imediato e abrupto no exato instante em que é liberado, devido ao atrito estático máximo.", "O sistema entra em ressonância divergente, aumentando sua energia cinética até o colapso estrutural da mola."), correctOptionIndex = 1, difficulty = "Avançada", subject = "Física"),
        Question(id = generateId(), text = "A Lei de Gauss para a eletrostática relaciona o fluxo elétrico através de uma superfície fechada à carga elétrica nela contida. Qual característica estrutural da força de Coulomb assegura a validade universal desta formulação integral?", options = listOf("A sua independência em relação à permissividade elétrica do meio dielétrico circundante.", "A sua dependência exata com o inverso do quadrado da distância, que garante a conservação espacial do fluxo em simetria esférica.", "O fato de atuar exclusivamente como força atrativa entre cargas de sinais opostos em repouso.", "A sua manifestação apenas em referenciais inerciais desprovidos de campos magnéticos de fundo."), correctOptionIndex = 1, difficulty = "Avançada", subject = "Física"),
        Question(id = generateId(), text = "O modelo atômico de Bohr para o átomo de hidrogênio mesclou mecânica clássica com condições quânticas pioneiras. Qual postulado ad hoc introduzido por Bohr justificava a estabilidade orbital frente à eletrodinâmica clássica?", options = listOf("A substituição da força eletrostática de Coulomb pela força nuclear forte nas interações entre elétron e próton.", "A premissa de que o elétron só poderia emitir radiação eletromagnética de forma contínua caso sua órbita fosse perfeitamente circular.", "A condição de que o momento angular orbital do elétron fosse quantizado em múltiplos inteiros da constante de Planck reduzida, definindo órbitas estacionárias que não irradiam.", "A adoção da equação de Schrödinger para mapear a probabilidade volumétrica de encontrar o elétron no interior do núcleo."), correctOptionIndex = 2, difficulty = "Avançada", subject = "Física"),
        Question(id = generateId(), text = "O Princípio da Equivalência é a pedra angular da Teoria da Relatividade Geral de Einstein. Qual analogia física fundamental esse princípio estabelece em referenciais locais?", options = listOf("A indistinguibilidade absoluta entre os efeitos de um campo gravitacional uniforme e os de um referencial uniformemente acelerado.", "A equivalência quantitativa direta entre a densidade de energia de um campo magnético e a de um campo elétrico no vácuo.", "A correspondência exata entre as forças de contração espacial de Lorentz e a dilatação temporal de eventos simultâneos.", "A paridade perfeita entre matéria e antimatéria na geração de ondas gravitacionais de baixa frequência."), correctOptionIndex = 0, difficulty = "Avançada", subject = "Física"),
        Question(id = generateId(), text = "A formulação matemática do efeito Doppler para ondas sonoras é assimétrica e depende de quem se move: a fonte ou o observador. Qual fator físico subjacente impõe essa quebra de simetria que não ocorre na luz no vácuo?", options = listOf("A natureza transversal das frentes de onda acústicas ao interagirem com os obstáculos no caminho livre médio.", "O aumento da massa inercial do observador em movimento, que altera o momento linear das partículas do meio.", "A necessidade de um meio material (como o ar) para a propagação do som, o qual define um referencial privilegiado para a medida das velocidades relativas.", "A dependência direta da velocidade do som em relação à frequência da fonte emissora devido à dispersão anômala do ar."), correctOptionIndex = 2, difficulty = "Avançada", subject = "Física"),
        Question(id = generateId(), text = "O ponto triplo de uma substância pura em um diagrama de fases indica a coexistência térmica simultânea das fases sólida, líquida e gasosa. De acordo com a Regra das Fases de Gibbs, qual é o número de graus de liberdade (variáveis intensivas independentes) desse estado termodinâmico?", options = listOf("Zero, pois a temperatura e a pressão estão fixadas de forma única e invariável pelas condições de equilíbrio múltiplo.", "Um, permitindo que a pressão seja alterada isotermicamente sem que haja mudança de fase estrutural.", "Dois, viabilizando a variação independente do volume e da entalpia da mistura.", "Três, correspondendo à capacidade de alterar pressão, temperatura e volume específico simultaneamente."), correctOptionIndex = 0, difficulty = "Avançada", subject = "Física"),
        Question(id = generateId(), text = "A Segunda Lei de Kepler, que afirma que o vetor raio-vetor varre áreas iguais em tempos iguais, descreve a cinemática orbital planetária. Em termos de mecânica clássica de campos centrais, essa lei é uma derivação direta de qual princípio de conservação?", options = listOf("Da conservação da energia mecânica total da órbita elíptica em torno do sol.", "Da conservação do momento angular do planeta, decorrente de a força gravitacional atuar puramente na direção radial (torque nulo).", "Da conservação do momento linear no eixo tangencial à trajetória elíptica.", "Da conservação da massa inercial do planeta durante os periélios devido às altas velocidades de translação."), correctOptionIndex = 1, difficulty = "Avançada", subject = "Física"),
        Question(id = generateId(), text = "A reflexão interna total é o fenômeno óptico responsável pela condução de luz no núcleo das fibras ópticas. Qual condição refrativa é fisicamente indispensável para que o feixe sofra esse confinamento ao atingir a interface?", options = listOf("A luz deve passar de um meio de menor índice de refração para um de maior índice, independentemente do ângulo de incidência.", "O ângulo de incidência crítico deve ser nulo, permitindo a propagação rasante perfeita ao longo do eixo cilíndrico.", "O feixe deve ser polarizado circularmente antes de ingressar no material cristalino de núcleo oco.", "A luz deve propagar-se de um meio mais refringente para um menos refringente e atingir a interface com um ângulo de incidência superior ao ângulo limite."), correctOptionIndex = 3, difficulty = "Avançada", subject = "Física"),
        Question(id = generateId(), text = "O diamagnetismo é uma propriedade magnética intrínseca a toda matéria, embora frequentemente ofuscada. Em nível subatômico, qual é o processo fundamental que gera a resposta diamagnética repulsiva a um campo magnético externo?", options = listOf("O alinhamento dos momentos dipolares magnéticos permanentes intrínsecos dos elétrons desemparelhados na banda de valência.", "A interação de troca quântica que alinha paralelamente os spins eletrônicos de átomos vizinhos na rede cristalina.", "A indução de correntes orbitais microscópicas nos elétrons, as quais geram um campo magnético induzido em sentido oposto ao campo aplicado, análogo à Lei de Lenz.", "O aprisionamento de monopolos magnéticos virtuais nos defeitos estruturais da estrutura cristalina amorfa."), correctOptionIndex = 2, difficulty = "Avançada", subject = "Física"),
        Question(id = generateId(), text = "O decaimento beta menos (\\$\\beta^-\\\$) altera a composição do núcleo atômico pela emissão de um elétron. Em termos do modelo padrão de partículas, qual interação fundamental governa esse processo transmutacional e o que ocorre no nível dos núcleons?", options = listOf("A interação forte, que funde um próton e um píon virtual para originar um nêutron estável.", "A interação fraca, que converte um nêutron em um próton, com a consequente emissão de um elétron e de um antineutrino do elétron.", "A força eletromagnética, responsável pela ionização espontânea dos elétrons mais internos da camada K.", "A gravitação quântica em nível nuclear, que ejeta elétrons para manter a constância da densidade do núcleo."), correctOptionIndex = 1, difficulty = "Avançada", subject = "Física"),
        Question(id = generateId(), text = "As ondas estacionárias formadas em cordas vibrantes ou cavidades ressonantes caracterizam-se por não transportarem energia através do meio. Cineticamente, como essa distribuição espacial invariável da energia é estabelecida?", options = listOf("Pela completa absorção da energia incidente pelos nós fixos nas fronteiras do meio material.", "Pela dispersão anômala das frentes de onda, que fraciona o pacote de energia em frequências inaudíveis.", "Pela superposição linear de duas ondas progressivas idênticas (mesma amplitude e frequência) que se propagam em sentidos opostos.", "Pela interrupção imediata da oscilação da fonte geradora ao atingir a frequência de ressonância natural do sistema."), correctOptionIndex = 2, difficulty = "Avançada", subject = "Física"),
        Question(id = generateId(), text = "A expansão livre e a mistura espontânea de dois gases ideais distintos, mantendo a temperatura isolada, ocorrem sem variação de energia interna ou entalpia. Termodinamicamente, o que atua como motor de irreversibilidade desse processo?", options = listOf("O aumento global do número de microestados acessíveis ao sistema, que maximiza a entropia configuracional.", "O choque inelástico entre moléculas de diferentes massas, que dissipa calor para o ambiente externo adjacente.", "A redução local da energia livre de Gibbs impulsionada pela condensação do gás mais pesado no fundo do recipiente.", "A diferença de pressões parciais, que atua realizando trabalho útil de expansão contra o vácuo circundante."), correctOptionIndex = 0, difficulty = "Avançada", subject = "Física"),
        Question(id = generateId(), text = "A força centrífuga, frequentemente percebida em veículos em curvas ou em carrosséis, é classificada como uma força fictícia pela mecânica newtoniana. Qual é a gênese física dessa sensação tátil em referenciais não inerciais em rotação?", options = listOf("A atração gravitacional anômala do centro geométrico de rotação, potencializada pela alta velocidade angular local.", "A força de reação da Terceira Lei de Newton (Ação e Reação) que a massa do corpo exerce sobre a força centrípeta central.", "A inércia translacional do próprio corpo, que tende a manter seu estado de movimento retilíneo uniforme, resistindo à mudança contínua de direção imposta pelo referencial curvo.", "A interação de forças eletromagnéticas repulsivas geradas pelo atrito estático no eixo de rotação giratório."), correctOptionIndex = 2, difficulty = "Avançada", subject = "Física"),
        Question(id = generateId(), text = "Na interpretação de Copenhague da mecânica quântica, o processo de medição destrói o determinismo contínuo da função de onda. Qual conceito matemático formaliza esta transição abrupta do estado quântico no momento de uma observação?", options = listOf("A evolução temporal estritamente unitária e reversível ditada pelo operador Hamiltoniano da equação de Schrödinger.", "A projeção instantânea do estado de superposição quântica para um único autoestado correspondente ao autovalor medido do operador associado ao observável.", "A transição probabilística da partícula pelo efeito túnel, atravessando a barreira de potencial do aparelho macroscópico de medida.", "O princípio da exclusão de Pauli, que força a função de onda espacial a tornar-se anti-simétrica na presença de bósons mediadores de força."), correctOptionIndex = 1, difficulty = "Avançada", subject = "Física")
    )

